package com.example.rag.service;

import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;
import com.baomidou.mybatisplus.core.conditions.update.LambdaUpdateWrapper;
import com.baomidou.mybatisplus.extension.plugins.pagination.Page;
import com.example.rag.dto.*;
import com.example.rag.persistence.entity.*;
import com.example.rag.persistence.mapper.*;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;
import java.time.LocalDateTime;
import java.util.*;

@Service
public class DocumentService {
 private final DocumentMapper documents;private final DocumentVersionMapper versions;private final KnowledgeBaseMapper knowledgeBases;private final FileObjectMapper files;
 public DocumentService(DocumentMapper documents,DocumentVersionMapper versions,KnowledgeBaseMapper knowledgeBases,FileObjectMapper files){this.documents=documents;this.versions=versions;this.knowledgeBases=knowledgeBases;this.files=files;}
 @Transactional public DocumentResponse create(DocumentCreateRequest req){KnowledgeBaseEntity kb=knowledgeBases.selectById(req.knowledgeBaseId());if(kb==null)throw missing("Knowledge base not found");LocalDateTime now=LocalDateTime.now();DocumentEntity d=new DocumentEntity();d.setId(UUID.randomUUID());d.setTenantId(kb.getTenantId());d.setKnowledgeBaseId(kb.getId());d.setDisplayName(req.displayName());d.setStatus("ACTIVE");d.setCreatedBy(kb.getCreatedBy());d.setCreatedAt(now);d.setUpdatedAt(now);documents.insert(d);return response(d);}
 @Transactional(readOnly=true) public DocumentPageResponse list(UUID kbId,String keyword,long page,long size){if(knowledgeBases.selectById(kbId)==null)throw missing("Knowledge base not found");Page<DocumentEntity> p=documents.selectPage(new Page<>(page,size),new LambdaQueryWrapper<DocumentEntity>().eq(DocumentEntity::getKnowledgeBaseId,kbId).isNull(DocumentEntity::getDeletedAt).like(keyword!=null&&!keyword.isBlank(),DocumentEntity::getDisplayName,keyword).orderByDesc(DocumentEntity::getUpdatedAt));return new DocumentPageResponse(p.getRecords().stream().map(this::response).toList(),p.getTotal(),page,size);}
 @Transactional(readOnly=true) public DocumentResponse get(UUID kbId,UUID id){DocumentEntity d=require(kbId,id,false);return response(d);}
 @Transactional public DocumentResponse update(UUID kbId,UUID id,DocumentUpdateRequest req){DocumentEntity d=require(kbId,id,true);d.setDisplayName(req.displayName());d.setUpdatedAt(LocalDateTime.now());documents.updateById(d);return response(d);}
 @Transactional public void delete(UUID kbId,UUID id){DocumentEntity d=require(kbId,id,true);LocalDateTime now=LocalDateTime.now();d.setDeletedAt(now);d.setUpdatedAt(now);d.setStatus("DELETED");documents.updateById(d);}
 @Transactional public DocumentVersionResponse createVersion(UUID documentId,DocumentVersionCreateRequest req){DocumentEntity d=documents.selectByIdForUpdate(documentId);if(d==null||d.getDeletedAt()!=null)throw missing("Document not found");FileObjectEntity f=files.selectByIdForUpdate(req.fileObjectId());if(f==null)throw missing("File not found");if(!Objects.equals(f.getTenantId(),d.getTenantId()))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"File not found");if(!"AVAILABLE".equals(f.getStorageStatus()))throw new ResponseStatusException(HttpStatus.CONFLICT,"File is not available");List<DocumentVersionEntity> latest=versions.selectList(new LambdaQueryWrapper<DocumentVersionEntity>().eq(DocumentVersionEntity::getDocumentId,documentId).orderByDesc(DocumentVersionEntity::getVersionNo).last("LIMIT 1"));int next=latest.isEmpty()?1:latest.get(0).getVersionNo()+1;LocalDateTime now=LocalDateTime.now();DocumentVersionEntity v=new DocumentVersionEntity();v.setId(UUID.randomUUID());v.setDocumentId(documentId);v.setVersionNo(next);v.setTenantId(d.getTenantId());v.setSourceFileId(f.getId());v.setSourceSha256(f.getSha256());v.setMediaType(f.getMediaType());v.setByteSize(f.getByteSize());v.setOriginalFilename(req.originalFilename());v.setStatus("UPLOADED");v.setCreatedBy(d.getCreatedBy());v.setCreatedAt(now);versions.insert(v);d.setUpdatedAt(now);documents.updateById(d);return versionResponse(v);}
 @Transactional(readOnly=true) public List<DocumentVersionResponse> listVersions(UUID documentId){DocumentEntity d=documents.selectById(documentId);if(d==null||d.getDeletedAt()!=null)throw missing("Document not found");return versions.selectList(new LambdaQueryWrapper<DocumentVersionEntity>().eq(DocumentVersionEntity::getDocumentId,documentId).orderByDesc(DocumentVersionEntity::getVersionNo)).stream().map(this::versionResponse).toList();}
 @Transactional(readOnly=true) public DocumentVersionResponse getVersion(UUID documentId,UUID versionId){DocumentEntity d=documents.selectById(documentId);if(d==null||d.getDeletedAt()!=null)throw missing("Document not found");DocumentVersionEntity v=versions.selectById(versionId);if(v==null||!documentId.equals(v.getDocumentId()))throw missing("Document version not found");return versionResponse(v);}
 @Transactional public DocumentResponse activate(UUID documentId,UUID versionId){DocumentEntity d=documents.selectByIdForUpdate(documentId);if(d==null||d.getDeletedAt()!=null)throw missing("Document not found");DocumentVersionEntity v=versions.selectById(versionId);if(v==null||!documentId.equals(v.getDocumentId()))throw missing("Document version not found");if(!"COMPLETED".equals(v.getStatus()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Version must be processed and validated before activation");LocalDateTime now=LocalDateTime.now();UUID oldId=d.getActiveVersionId();if(oldId!=null&&!oldId.equals(versionId))versions.update(null,new LambdaUpdateWrapper<DocumentVersionEntity>().eq(DocumentVersionEntity::getId,oldId).set(DocumentVersionEntity::getRetiredAt,now));versions.update(null,new LambdaUpdateWrapper<DocumentVersionEntity>().eq(DocumentVersionEntity::getId,versionId).set(DocumentVersionEntity::getActivatedAt,now).set(DocumentVersionEntity::getRetiredAt,null));d.setActiveVersionId(versionId);d.setUpdatedAt(now);documents.updateById(d);return response(d);}
 private DocumentEntity require(UUID kb,UUID id,boolean lock){DocumentEntity d=lock?documents.selectByIdForUpdate(id):documents.selectById(id);if(d==null||d.getDeletedAt()!=null||!kb.equals(d.getKnowledgeBaseId()))throw missing("Document not found");return d;}
 private DocumentResponse response(DocumentEntity d){DocumentVersionResponse active=null;long count=versions.selectCount(new LambdaQueryWrapper<DocumentVersionEntity>().eq(DocumentVersionEntity::getDocumentId,d.getId()));if(d.getActiveVersionId()!=null){DocumentVersionEntity v=versions.selectById(d.getActiveVersionId());if(v!=null&&d.getId().equals(v.getDocumentId()))active=versionResponse(v);}return new DocumentResponse(d.getId(),d.getTenantId(),d.getKnowledgeBaseId(),d.getDisplayName(),d.getStatus(),d.getActiveVersionId(),count,active,d.getCreatedAt(),d.getUpdatedAt());}
 private DocumentVersionResponse versionResponse(DocumentVersionEntity v){return new DocumentVersionResponse(v.getId(),v.getDocumentId(),v.getVersionNo(),v.getSourceFileId(),HexFormat.of().formatHex(v.getSourceSha256()),v.getMediaType(),v.getByteSize(),v.getOriginalFilename(),v.getStatus(),v.getCreatedAt(),v.getActivatedAt());}
 private ResponseStatusException missing(String m){return new ResponseStatusException(HttpStatus.NOT_FOUND,m);}
}
